method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0
    ensures |result| == |xs| - 1
    ensures forall i :: 0 <= i < |result| ==> result[i] == xs[i + 1] * (i + 1)
{
    var n := |xs| - 1;
    result := new int[n];
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant forall j :: 0 <= j < i ==> result[j] == xs[j + 1] * (j + 1)
    {
        result[i] := xs[i + 1] * (i + 1);
        i := i + 1;
    }
}
